(()=>{'use strict';
const KEY='life_os_data_v1', VERSION=2, today=()=>LifeCore.day(new Date()), uid=()=>crypto.randomUUID?crypto.randomUUID():String(Date.now())+Math.random();
const defaults=()=>({version:VERSION,created:new Date().toISOString(),settings:{theme:'auto',home:['tasks','events','routines','admin','reminders','focus'],weekStart:1},tasks:[],events:[],reminders:[],routines:[],notes:[],lists:[],admin:[],focus:[],calendarSources:[]});
let db;try{db=JSON.parse(localStorage.getItem(KEY)||'null')||defaults()}catch{document.getElementById('app').textContent='Le stockage LIFE OS est illisible. Les données originales ont été conservées. Restaure une sauvegarde depuis une nouvelle installation de test, sans effacer le stockage original.';return}for(const k of Object.keys(defaults()))if(db[k]===undefined)db[k]=defaults()[k];
try{db=LifeCore.validate({app:'LIFE_OS',version:Math.min(db.version||1,2),data:db},defaults())}catch(e){document.getElementById('app').textContent='Données locales invalides : '+e.message+'. Sauvegarde le stockage avant toute intervention.';return}
let page='home', sub='', modal=null, calDate=new Date(), search='', timer=null;
const TIMER_KEY='life_os_focus_timer_v1';
let focusTimer=null;try{focusTimer=JSON.parse(localStorage.getItem(TIMER_KEY)||'null')}catch{}
function saveFocusTimer(){try{if(focusTimer)localStorage.setItem(TIMER_KEY,JSON.stringify(focusTimer));else localStorage.removeItem(TIMER_KEY)}catch{}}
function focusRemaining(){return focusTimer?Math.max(0,focusTimer.running?Math.ceil((focusTimer.endAt-Date.now())/1000):focusTimer.remaining):0}
function focusTick(){if(page!=='focus'||!focusTimer)return;const clock=document.getElementById('focusClock');if(clock){const r=focusRemaining();clock.textContent=String(Math.floor(r/60)).padStart(2,'0')+':'+String(r%60).padStart(2,'0');const label=document.getElementById('focusState');if(label)label.textContent=r===0?'Temps écoulé — enregistre la session pour la comptabiliser':focusTimer.running?'En cours':'En pause';}}
setInterval(focusTick,500);

const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const persist=()=>{try{localStorage.setItem(KEY,JSON.stringify(db));return true}catch(e){try{db=JSON.parse(localStorage.getItem(KEY))||defaults()}catch{}alert('Enregistrement impossible : stockage saturé ou bloqué. La modification n’a pas été enregistrée. Exporte une sauvegarde.');return false}};
const get=(kind,id)=>db[kind].find(x=>x.id===id),fmt=x=>x?new Date(x+'T12:00:00').toLocaleDateString('fr-FR'):'Sans date';
const dateAdd=(str,repeat,anchor)=>LifeCore.add(str,repeat,anchor);
const tomorrow=()=>{const d=new Date();d.setDate(d.getDate()+1);return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-')};
const due=(x)=>x.date||x.due||'', sortDue=(a,b)=>(due(a)||'9999').localeCompare(due(b)||'9999');
const sections=[['home','Accueil','⌂'],['calendar','Calendrier','▦'],['tasks','Tâches','✓'],['reminders','Rappels','◷'],['routines','Habitudes','↻'],['notes','Notes & listes','▤'],['admin','Administration','▣'],['weekly','Semaine','◫'],['focus','Concentration','◎'],['search','Recherche','⌕'],['stats','Analyses','▥'],['data','Paramètres','⚙']];
const nav=(p)=>{page=p;sub='';modal=null;render();scrollTo(0,0)};
const b=(label,action,cls='alt')=>`<button class="btn ${cls}" data-act="${action}">${label}</button>`;
const count=(kind)=>db[kind].length,open=(kind,id='')=>{modal={kind,id};render()};
const applyTheme=()=>{document.body.classList.toggle('light',db.settings.theme==='light'||(db.settings.theme==='auto'&&matchMedia('(prefers-color-scheme: light)').matches))};

function baseNotes(){return `<h1>Notes et listes</h1><div class="tabs"><button class="${sub!=='lists'?'active':''}" data-act="filter:">Notes</button><button class="${sub==='lists'?'active':''}" data-act="filter:lists">Listes intelligentes</button></div>${sub==='lists'?`${b('+ Nouvelle liste','add:lists','')}<div class="panel" style="margin-top:15px">${db.lists.map(x=>`<div class="item"><div class="details"><b>${esc(x.title)}</b>${(x.items||[]).map((v,i)=>`<div><label><input type="checkbox" style="width:auto" data-check="${esc(x.id)}:${i}" ${v.done?'checked':''}> ${esc(v.text)}</label></div>`).join('')}</div><div class="actions">${b('Modifier',`edit:lists:${x.id}`)}${b('Supprimer',`delete:lists:${x.id}`,'danger')}</div></div>`).join('')||'<div class="empty">Aucune liste</div>'}</div>`:`${b('+ Nouvelle note','add:notes','')}<div class="panel" style="margin-top:15px">${db.notes.map(x=>item('notes',x,`${esc((x.body||'').slice(0,140))}${x.attachment?' · 📎 Pièce jointe':''}`)).join('')||'<div class="empty">Aucune note</div>'}</div>`}`}
function focus(){const mins=db.focus.reduce((n,x)=>n+Number(x.minutes||0),0),r=focusRemaining(),clock=String(Math.floor(r/60)).padStart(2,'0')+':'+String(r%60).padStart(2,'0');return `<h1>Concentration</h1><div class="panel"><h2>Minuteur de concentration</h2><div class="fields"><div><label for="focusMinutes">Durée prévue (minutes)</label><input id="focusMinutes" type="number" min="1" max="240" value="${focusTimer?focusTimer.planned:25}" ${focusTimer?'disabled':''}></div><div><label for="focusTitle">Objet de la session</label><input id="focusTitle" placeholder="Lecture, administratif, projet…" value="${esc(focusTimer?.title||'')}" ${focusTimer?'disabled':''}></div></div><div id="focusClock" class="focus-clock" role="timer" aria-live="off">${focusTimer?clock:'25:00'}</div><div id="focusState" class="muted" style="text-align:center;margin-bottom:12px">${!focusTimer?'Prêt à démarrer':r===0?'Temps écoulé — enregistre la session pour la comptabiliser':focusTimer.running?'En cours':'En pause'}</div><div class="actions">${!focusTimer?b('▶ Démarrer','focusstart',''):focusTimer.running?b('⏸ Pause','focuspause',''):b('▶ Reprendre','focusresume','')}${focusTimer?b('✓ Terminer et enregistrer','focusfinish',''):''}${focusTimer?b('Annuler','focuscancel','danger'):''}</div><p class="muted">Le compte à rebours retrouve le temps écoulé après verrouillage ou réouverture. Aucune notification en arrière-plan n'est garantie. Une session n'est comptabilisée qu'après confirmation.</p></div><div class="panel"><h2>Enregistrement manuel</h2><p class="muted">Pour une session déjà réalisée, sans minuteur.</p><div class="fields"><div><label for="manualFocusMinutes">Durée réelle (minutes)</label><input id="manualFocusMinutes" type="number" min="1" max="240" value="25"></div><div><label for="manualFocusTitle">Objet</label><input id="manualFocusTitle" placeholder="Lecture, administratif, projet…"></div></div><div class="actions" style="margin-top:12px">${b('Enregistrer une session terminée','focusdone','')}</div></div><div class="panel"><h2>Historique · ${mins} minutes au total</h2>${db.focus.slice().reverse().map(x=>item('focus',x,`${x.minutes} min · ${fmt(x.date)}`)).join('')||'<div class="empty">Aucune session</div>'}</div>`}
function universal(){const q=search.toLocaleLowerCase(),kinds=['tasks','events','reminders','routines','notes','lists','admin'];const hits=kinds.flatMap(k=>db[k].filter(x=>[x.title,x.name,x.body,x.notes,x.category].join(' ').toLocaleLowerCase().includes(q)).map(x=>({k,x})));return `<h1>Recherche universelle</h1><div class="panel"><input id="searchInput" aria-label="Recherche universelle" placeholder="Chercher dans toutes les rubriques" value="${esc(search)}"><div style="margin-top:12px">${q?hits.map(({k,x})=>item(k,x,esc(k))).join('')||'<div class="empty">Aucun résultat</div>':'<div class="empty">Saisis un mot pour rechercher</div>'}</div></div>`}
function baseStats(){const done=db.tasks.filter(x=>x.done).length,total=db.tasks.length,rate=total?Math.round(100*done/total):0,mins=db.focus.reduce((n,x)=>n+Number(x.minutes||0),0),doneR=db.routines.reduce((n,x)=>n+(x.history||[]).length,0);return `<h1>Statistiques personnelles</h1><div class="grid">${[['Tâches accomplies',`${done}/${total}`],['Taux de réalisation',rate+' %'],['Routines cochées',doneR],['Concentration',mins+' min'],['Notes',count('notes')],['Événements',count('events')]].map(([l,v])=>`<div class="panel"><small>${l}</small><div class="metric">${v}</div></div>`).join('')}</div><div class="panel"><h2>Progression des tâches</h2><div class="bar"><span style="width:${rate}%"></span></div><p class="muted">Les données absentes ne sont pas comptées comme des tâches manquées.</p></div>`}
function field(name,label,type='text',val='',opts=''){return `<div class="field"><label for="f_${name}">${label}</label>${type==='textarea'?`<textarea id="f_${name}" name="${name}">${esc(val)}</textarea>`:type==='select'?`<select id="f_${name}" name="${name}">${opts.split('|').map(v=>`<option ${v===String(val)?'selected':''}>${esc(v)}</option>`).join('')}</select>`:`<input id="f_${name}" name="${name}" type="${type}" value="${esc(val)}" ${type==='number'?'min="0"':''}>`}</div>`}
function baseModalHTML(){if(!modal)return '';const {kind,id}=modal,x=id?get(kind,id):{};if(id&&!x){modal=null;return ''}const title=kind==='tasks'?'Tâche':kind==='events'?'Événement':kind==='reminders'?'Rappel':kind==='routines'?'Routine':kind==='notes'?'Note':kind==='lists'?'Liste':kind==='admin'?'Dossier administratif':'Session';let f=field('title','Titre','text',x.title||'');if(kind==='tasks'){f+=`<div class="fields">${field('due','Échéance','date',x.due)}${field('priority','Priorité','select',x.priority||'Normale','Basse|Normale|Haute|Urgente')}${field('repeat','Récurrence','select',x.repeat||'Aucune','Aucune|Quotidienne|Hebdomadaire|Mensuelle')}${field('status','Statut','select',x.done?'Terminée':'À faire','À faire|Terminée')}</div>`;f+=`<div class="field"><label>Prérequis (cocher les tâches à terminer avant celle-ci)</label>${db.tasks.filter(t=>t.id!==id).map(t=>`<label><input type="checkbox" name="dep" value="${esc(t.id)}" style="width:auto" ${(x.depends||[]).includes(t.id)?'checked':''}> ${esc(t.title)}</label>`).join('')||'<small>Aucune autre tâche</small>'}</div>`}if(kind==='events')f+=`<div class="fields">${field('date','Date','date',x.date||today())}${field('time','Heure','time',x.time||'09:00')}${field('calendar','Calendrier','text',x.calendar||'Personnel')}</div>`;if(kind==='reminders')f+=`<div class="fields">${field('date','Date','date',x.date||today())}${field('time','Heure','time',x.time||'09:00')}${field('priority','Priorité','select',x.priority||'Normale','Basse|Normale|Haute|Urgente')}</div>`;if(kind==='routines')f+=`<div class="fields">${field('frequency','Fréquence','select',x.frequency||'Quotidienne','Quotidienne|Jours ouvrés|Hebdomadaire|Personnalisée')}${field('goal','Objectif','text',x.goal||'')}</div>`;if(kind==='notes')f+=field('body','Contenu et liens','textarea',x.body||'');if(kind==='lists')f+=field('lines','Éléments (une ligne par élément)','textarea',(x.items||[]).map(v=>v.text).join('\n'));if(kind==='admin')f+=`<div class="fields">${field('date','Échéance','date',x.date||'')}${field('category','Catégorie','text',x.category||'Général')}</div>`;if(['tasks','events','reminders','admin'].includes(kind))f+=field('notes','Notes','textarea',x.notes||'');if(['notes','admin'].includes(kind))f+=`<div class="field"><label>Pièce jointe (500 Ko maximum)</label><input type="file" id="attachment" accept="image/*,.pdf,.txt">${x.attachment?'<small>Pièce jointe enregistrée (laisser vide pour la conserver)</small>':''}</div>`;return `<div class="modalback" id="modalback"><div class="modal" role="dialog" aria-modal="true" aria-labelledby="modalTitle"><h2 id="modalTitle">${id?'Modifier':'Ajouter'} · ${title}</h2><form id="entityForm" data-kind="${kind}" data-id="${esc(id)}">${f}<div class="actions"><button class="btn" type="submit">Enregistrer</button>${b('Annuler','close')}</div></form></div></div>`}
function render(){applyTheme();const content={home,calendar,tasks,reminders,routines,notes,admin,weekly,focus,search:universal,stats,data}[page]();document.getElementById('app').innerHTML=`<header><div class="brand"><img src="icon.svg" alt="" width="36" height="36"><div><strong>LIFE OS</strong><div class="muted" style="font-size:11px">Personal Organizer</div></div></div><span class="pill">${navigator.onLine?'Espace indépendant':'Hors connexion'} · 2.0</span></header><main class="shell"><nav class="sidebar" aria-label="Navigation principale">${sections.map(([p,l,ico])=>`<button data-nav="${p}" class="${page===p?'active':''}">${ico} ${l}</button>`).join('')}</nav><div class="content">${content}</div></main><nav class="mobile-nav" aria-label="Navigation principale mobile">${[['home','Accueil','⌂'],['calendar','Calendrier','▦'],['tasks','Tâches','✓'],['routines','Habitudes','↻'],['data','Plus','☰']].map(([p,l,ico])=>`<button data-nav="${p}" class="${page===p?'active':''}">${ico}<div>${l}</div></button>`).join('')}</nav>${modalHTML()}`;if(page==='data')offlineStatus();if(modal){document.querySelector('.modal input')?.focus()}const sel=document.getElementById('themeSelect');if(sel)sel.value=db.settings.theme;}
const csvSafe=v=>{const s=String(v??'');return /^[=+@-]/.test(s)?"'"+s:s};
const download=(name,body,mime)=>{const url=URL.createObjectURL(new Blob([body],{type:mime}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),5000)};
function baseAction(s){const [cmd,kind,id]=s.split(':');if(cmd==='add')open(kind);if(cmd==='edit')open(kind,id);if(cmd==='close'){modal=null;render()}if(cmd==='filter'){sub=kind||'';render()}if(cmd==='month'){calDate.setDate(1);calDate.setMonth(calDate.getMonth()+Number(kind));render()}if(cmd==='toggle'){const x=get(kind,id);if(!x)return;if(!x.done){const unmet=(x.depends||[]).map(d=>get('tasks',d)).filter(d=>!d||!d.done);if(unmet.length){alert('Prérequis non terminés : '+unmet.map(d=>d?.title||'Tâche supprimée').join(', '));return}}x.done=!x.done;if(x.done&&kind==='tasks'&&x.repeat&&x.repeat!=='Aucune'&&x.due){const next=dateAdd(x.due,x.repeat,x.repeatAnchor||x.due);if(next&&!db.tasks.some(t=>t.recurrenceParent===x.id&&t.due===next)){db.tasks.push({...x,id:uid(),done:false,due:next,recurrenceParent:x.id,repeatAnchor:x.repeatAnchor||x.due,subtasks:(x.subtasks||[]).map(t=>({...t,done:false})),depends:[]})}}persist();render()}if(cmd==='delete'){const x=get(kind,id);if(x&&confirm('Supprimer définitivement « '+(x.title||x.name)+' » ?')){db[kind]=db[kind].filter(y=>y.id!==id);persist();render()}}if(cmd==='snooze'){const x=get('reminders',kind);if(x){const d=new Date((x.date||today())+'T12:00:00');d.setDate(d.getDate()+1);x.date=d.toLocaleDateString('en-CA');persist();render()}}if(cmd==='routine'){const x=get('routines',kind);if(x){if(x.paused||!LifeCore.scheduled(x,today())){alert('Cette journée est en pause ou non planifiée.');return}x.history=x.history||[];x.history=x.history.includes(today())?x.history.filter(d=>d!==today()):[...x.history,today()];persist();render()}}if(cmd==='pause'){const x=get('routines',kind);if(x){x.paused=!x.paused;x.pauseRanges=x.pauseRanges||[];if(x.paused)x.pauseRanges.push({start:today()});else {const r=x.pauseRanges.findLast(r=>!r.end);if(r)r.end=LifeCore.shift(today(),-1)}persist();render()}}if(cmd==='up'){const i=Number(kind);if(i>0){[db.settings.home[i-1],db.settings.home[i]]=[db.settings.home[i],db.settings.home[i-1]];persist();render()}}if(cmd==='focusstart'){const planned=Number(document.getElementById('focusMinutes').value),title=document.getElementById('focusTitle').value.trim()||'Concentration';if(!Number.isInteger(planned)||planned<1||planned>240){alert('Durée invalide (1 à 240 minutes)');return}focusTimer={planned,title,remaining:planned*60,running:true,endAt:Date.now()+planned*60000,startedAt:Date.now(),elapsed:0};saveFocusTimer();render()}
if(cmd==='focuspause'&&focusTimer){focusTimer.remaining=focusRemaining();focusTimer.elapsed+=Math.max(0,Date.now()-focusTimer.startedAt);focusTimer.running=false;saveFocusTimer();render()}
if(cmd==='focusresume'&&focusTimer){if(focusRemaining()===0){alert('Le temps est écoulé. Termine ou annule cette session.');return}focusTimer.running=true;focusTimer.startedAt=Date.now();focusTimer.endAt=Date.now()+focusTimer.remaining*1000;saveFocusTimer();render()}
if(cmd==='focuscancel'&&focusTimer&&confirm('Annuler le minuteur sans enregistrer cette session ?')){focusTimer=null;saveFocusTimer();render()}
if(cmd==='focusfinish'&&focusTimer){const ms=focusTimer.elapsed+(focusTimer.running?Math.min(focusTimer.planned*60000-focusTimer.elapsed,Math.max(0,Date.now()-focusTimer.startedAt)):0);const minutes=Math.min(focusTimer.planned,Math.round(ms/60000));if(minutes<1){alert('Moins d’une minute effectuée : aucune session enregistrée.');return}if(!confirm('Enregistrer '+minutes+' minute(s) de concentration ?'))return;db.focus.push({id:uid(),title:focusTimer.title,minutes,date:today()});if(!persist())return;focusTimer=null;saveFocusTimer();render()}
if(cmd==='focusdone'){const minutes=Number(document.getElementById('manualFocusMinutes').value),title=document.getElementById('manualFocusTitle').value.trim()||'Concentration';if(!Number.isFinite(minutes)||minutes<1||minutes>240){alert('Durée invalide');return}db.focus.push({id:uid(),title,minutes,date:today()});persist();render()}if(cmd==='backup')download('LIFE_OS_sauvegarde_'+today()+'.json',JSON.stringify({app:'LIFE_OS',version:VERSION,exported:new Date().toISOString(),data:db},null,2),'application/json');if(cmd==='restore')restoreBackup();if(cmd==='csv'){const cols=['Titre','Date','Priorité','Terminée'];const csv=[cols,...db.tasks.map(x=>[x.title,x.due||'',x.priority||'',x.done?'Oui':'Non'])].map(row=>row.map(v=>'"'+csvSafe(v).replace(/"/g,'""')+'"').join(';')).join('\r\n');download('LIFE_OS_taches.csv','\ufeff'+csv,'text/csv;charset=utf-8')}if(cmd==='exportics')exportICS();if(cmd==='ics')importICS();if(cmd==='reset'&&confirm('ATTENTION : effacer toutes les données LIFE OS de ce navigateur ? Cette action est irréversible sans sauvegarde.')&&confirm('Confirmer la suppression définitive ?')){db=defaults();persist();render()}}
function exportICS(){const clean=x=>String(x||'').replace(/\\/g,'\\\\').replace(/\n/g,'\\n').replace(/[,;]/g,c=>'\\'+c);const lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//LIFE OS//Personal Organizer//FR','CALSCALE:GREGORIAN'];for(const x of db.events){if(!x.date)continue;const suffix=x.time?'T'+x.time.replace(':','')+'00':'',stamp=x.date.replace(/-/g,'')+suffix,tz=x.timeZone?';TZID='+x.timeZone:'';lines.push('BEGIN:VEVENT','UID:'+clean(x.importUid||x.id+'@life-os'),'DTSTAMP:'+new Date().toISOString().replace(/[-:]/g,'').split('.')[0]+'Z',(x.time?'DTSTART'+tz:'DTSTART;VALUE=DATE')+':'+stamp,'SUMMARY:'+clean(x.title),'DESCRIPTION:'+clean(x.notes),'X-LIFE-OS-CALENDAR:'+clean(x.calendar||'Personnel'));if(x.time)lines.push('DURATION:PT'+Number(x.duration||60)+'M');if(x.repeat&&x.repeat!=='Aucune'){lines.push('X-LIFE-OS-REPEAT:'+x.repeat,'X-LIFE-OS-ANCHOR:'+(x.repeatAnchor||x.date));if(x.repeatUntil)lines.push('X-LIFE-OS-UNTIL:'+x.repeatUntil);if(x.repeatCount)lines.push('X-LIFE-OS-COUNT:'+x.repeatCount);const horizon=LifeCore.day(new Date(new Date().getFullYear()+5,11,31)),dates=LifeCore.occurrences(x,x.date,horizon).slice(1).map(v=>v.date.replace(/-/g,'')+suffix);if(dates.length)lines.push((x.time?'RDATE'+tz:'RDATE;VALUE=DATE')+':'+dates.join(','));}lines.push('END:VEVENT')}lines.push('END:VCALENDAR');const folded=lines.flatMap(line=>{const out=[];let row='',bytes=0;for(const c of line){const n=c.codePointAt(0),size=n<128?1:n<2048?2:n<65536?3:4;if(bytes+size>70){out.push(row);row=' ';bytes=1}row+=c;bytes+=size}out.push(row);return out});download('LIFE_OS_calendrier.ics',folded.join('\r\n'),'text/calendar');alert('Calendrier exporté. Pour les autres applications, les récurrences sont matérialisées sur les 5 prochaines années. Le JSON reste la sauvegarde complète.');}
function importICS(){const input=document.createElement('input');input.type='file';input.accept='.ics,text/calendar';input.onchange=async()=>{try{if(!input.files.length)return;if(input.files[0].size>2000000)throw Error('Calendrier supérieur à 2 Mo');const text=await input.files[0].text(),blocks=text.replace(/\r?\n[ \t]/g,'').split('BEGIN:VEVENT').slice(1),draft=structuredClone(db);let added=0,skipped=0;const unescape=s=>s.replace(/\\n/gi,'\n').replace(/\\([,;\\])/g,'$1');for(const raw of blocks){const val=k=>(raw.match(new RegExp('(?:^|\\n)'+k+'(?:;[^:]*)?:([^\\r\\n]*)'))||[])[1]||'';const dt=val('DTSTART'),name=unescape(val('SUMMARY')),uidValue=val('UID');if(!dt||!name||val('RECURRENCE-ID')||val('EXDATE')){skipped++;continue}if(uidValue&&draft.events.some(x=>x.importUid===uidValue||x.id+'@life-os'===uidValue))continue;const date=dt.slice(0,4)+'-'+dt.slice(4,6)+'-'+dt.slice(6,8),time=dt.includes('T')?dt.split('T')[1].slice(0,2)+':'+dt.split('T')[1].slice(2,4):'';if(!LifeCore.validDate(date)){skipped++;continue}const tzMatch=raw.match(/(?:^|\n)DTSTART[^:]*;TZID=([^;:\r\n]+)/),timeZone=tzMatch?tzMatch[1]:dt.endsWith('Z')?'UTC':'';try{if(timeZone)new Intl.DateTimeFormat('fr',{timeZone}).format()}catch{skipped++;continue}let repeat=val('X-LIFE-OS-REPEAT'),repeatCount=Number(val('X-LIFE-OS-COUNT'))||undefined,repeatUntil=val('X-LIFE-OS-UNTIL')||undefined;const rr=val('RRULE');if(rr&&!repeat){const parts=Object.fromEntries(rr.split(';').map(p=>p.split('=')));if(Object.keys(parts).some(k=>!['FREQ','COUNT','UNTIL','INTERVAL'].includes(k))||(parts.INTERVAL&&parts.INTERVAL!=='1')){skipped++;continue}repeat=({DAILY:'Quotidienne',WEEKLY:'Hebdomadaire',MONTHLY:'Mensuelle',YEARLY:'Annuelle'})[parts.FREQ];if(!repeat){skipped++;continue}repeatCount=Number(parts.COUNT)||undefined;repeatUntil=parts.UNTIL?parts.UNTIL.slice(0,4)+'-'+parts.UNTIL.slice(4,6)+'-'+parts.UNTIL.slice(6,8):undefined;}if(val('RDATE')&&!repeat){skipped++;continue}if(repeat&&!['Quotidienne','Hebdomadaire','Mensuelle','Annuelle'].includes(repeat)){skipped++;continue}draft.events.push({id:uid(),importUid:uidValue||undefined,title:name,date,time,timeZone,duration:(()=>{const dur=val('DURATION').match(/^PT(?:(\d+)H)?(?:(\d+)M)?$/);if(dur)return Number(dur[1]||0)*60+Number(dur[2]||0);const end=val('DTEND');if(end&&time){const ed=end.slice(0,4)+'-'+end.slice(4,6)+'-'+end.slice(6,8),et=end.includes('T')?end.slice(9,11)+':'+end.slice(11,13):'00:00';return Math.max(1,(LifeCore.timestamp(ed,et,timeZone)-LifeCore.timestamp(date,time,timeZone))/60000)}return 60})(),calendar:unescape(val('X-LIFE-OS-CALENDAR'))||'Import ICS',notes:unescape(val('DESCRIPTION')),repeat:repeat||'Aucune',repeatCount,repeatUntil,repeatAnchor:val('X-LIFE-OS-ANCHOR')||date});added++}db=draft;if(!persist())return;render();alert(added+' événement(s) importé(s). '+skipped+' ignoré(s) : dates, exceptions ou règles non prises en charge. Les doublons UID sont ignorés.')}catch(e){alert(e.message)}};input.click()}
async function saveForm(form){try{const kind=form.dataset.kind,id=form.dataset.id,old=id?get(kind,id):null,x=old?structuredClone(old):{id:uid()},fd=new FormData(form);for(const [k,v]of fd.entries())if(!['dep','weekday','attachment'].includes(k))x[k]=String(v);x.title=String(fd.get('title')||'').trim();if(!x.title)throw Error('Le titre est obligatoire');for(const f of ['due','date'])if(x[f]&&!LifeCore.validDate(x[f]))throw Error('Date invalide');if(['tasks','events','admin'].includes(kind)){const raw=String(fd.get('alertLines')||'');x.alerts=raw?raw.split(',').map(v=>Number(v.trim())):[];if(x.alerts.some(v=>!Number.isInteger(v)||v<0||v>525600))throw Error('Rappels invalides : indique des minutes positives séparées par des virgules.');x.alerts=[...new Set(x.alerts)];delete x.alertLines;}if(kind==='tasks'){if(x.repeat&&x.repeat!=='Aucune'&&!x.due)x.due=today();if(!old||old.due!==x.due||old.repeat!==x.repeat)x.repeatAnchor=x.due;x.depends=fd.getAll('dep').map(String);const visit=(tid,seen=new Set())=>{if(tid===x.id)return true;if(seen.has(tid))return false;seen.add(tid);return (get('tasks',tid)?.depends||[]).some(v=>visit(v,seen))};if(x.depends.some(d=>visit(d)))throw Error('Dépendance circulaire interdite');x.subtasks=String(fd.get('subtaskLines')||'').split('\n').map(t=>t.trim()).filter(Boolean).map(text=>({text,done:!!old?.subtasks?.find(t=>t.text===text&&t.done)}));delete x.subtaskLines;x.done=fd.get('status')==='Terminée';delete x.status;if(x.done&&(x.depends.some(d=>!get('tasks',d)?.done)||x.subtasks.some(t=>!t.done)))throw Error('Termine les prérequis et sous-tâches avant la tâche principale.');}if(kind==='routines'){x.history=x.history||[];x.paused=!!x.paused;x.weekdays=fd.getAll('weekday').map(Number);x.target=Number(fd.get('target'));if(!Number.isInteger(x.target)||x.target<1||x.target>7)throw Error('Objectif hebdomadaire : 1 à 7');if(['Personnalisée','Hebdomadaire'].includes(x.frequency)&&!x.weekdays.length)throw Error('Choisis au moins un jour.');delete x.weekday;}if(kind==='events'){x.repeatCount=fd.get('repeatCount')?Number(fd.get('repeatCount')):undefined;if(x.repeatCount!==undefined&&(!Number.isInteger(x.repeatCount)||x.repeatCount<1||x.repeatCount>20000))throw Error('Nombre d’occurrences invalide (1 à 20000)');if(x.repeatUntil&&!LifeCore.validDate(x.repeatUntil))throw Error('Date de fin invalide');if(x.timeZone){try{new Intl.DateTimeFormat('fr',{timeZone:x.timeZone}).format()}catch{throw Error('Fuseau horaire IANA invalide (exemple : Europe/Berlin).')}}if(!Number.isFinite(LifeCore.timestamp(x.date,x.time,x.timeZone)))throw Error('Cette heure n’existe pas dans ce fuseau (changement d’heure).');x.duration=Number(x.duration||60);if(!Number.isFinite(x.duration)||x.duration<1||x.duration>10080)throw Error('Durée invalide');if(!old||old.date!==x.date||old.repeat!==x.repeat)x.repeatAnchor=x.date;}if(kind==='lists'){x.items=String(fd.get('lines')||'').split('\n').map(t=>t.trim()).filter(Boolean).map(text=>({text,done:!!old?.items?.find(t=>t.text===text&&t.done)}));delete x.lines;}const file=form.querySelector('#attachment')?.files?.[0];if(file){if(file.size>500000)throw Error('Pièce jointe supérieure à 500 Ko');if(!file.type.startsWith('image/')&&!['application/pdf','text/plain'].includes(file.type))throw Error('Format de document non pris en charge');x.attachment=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve({name:file.name,data:r.result,type:file.type});r.onerror=()=>reject(Error('Lecture du document impossible'));r.readAsDataURL(file)})}const draft=structuredClone(db);if(id)draft[kind][draft[kind].findIndex(t=>t.id===id)]=x;else draft[kind].push(x);if(kind==='tasks'&&x.done&&!old?.done&&x.repeat&&x.repeat!=='Aucune'&&x.due){const next=dateAdd(x.due,x.repeat,x.repeatAnchor||x.due);if(next&&!draft.tasks.some(t=>t.recurrenceParent===x.id&&t.due===next))draft.tasks.push({...x,id:uid(),done:false,due:next,recurrenceParent:x.id,repeatAnchor:x.repeatAnchor||x.due,subtasks:x.subtasks.map(t=>({...t,done:false})),depends:[]})}db=draft;if(!persist())return;modal=null;render()}catch(e){alert(e.message)}}
document.addEventListener('click',e=>{const navEl=e.target.closest('[data-nav]');if(navEl)return nav(navEl.dataset.nav);const btn=e.target.closest('[data-act]');if(btn)return action(btn.dataset.act)});document.addEventListener('submit',e=>{if(e.target.id==='entityForm'){e.preventDefault();saveForm(e.target)}});document.addEventListener('change',e=>{if(e.target.id==='themeSelect'){db.settings.theme=e.target.value;persist();render()}if(e.target.dataset.check){const [id,i]=e.target.dataset.check.split(':'),x=get('lists',id);if(x?.items[Number(i)]){x.items[Number(i)].done=e.target.checked;persist()}}});document.addEventListener('input',e=>{if(e.target.id==='searchInput'){search=e.target.value;const pos=e.target.selectionStart;render();const el=document.getElementById('searchInput');el.focus();el.setSelectionRange(pos,pos)}});
let homeView='today',customizing=false,calView='month',selectedDate=today(),taskQuery='',taskCategory='',taskProject='',noteQuery='',adminView='active',proposal=[];
const empty=t=>`<div class="empty">${t}</div>`,title=(t,button='')=>`<div class="page-title"><div><small>MON ORGANISATEUR</small><h1>${t}</h1></div>${button}</div>`;
const weekDays=()=>{const d=new Date(today()+'T12:00:00');d.setDate(d.getDate()-(d.getDay()+6)%7);return Array.from({length:7},(_,i)=>LifeCore.shift(LifeCore.day(d),i))};
const tabs=(arr,value,prefix)=>`<div class="tabs">${arr.map(([v,l])=>b(l,`${prefix}:${v}`,value===v?'selected':'alt')).join('')}</div>`;
function streak(x){return LifeCore.streak(x,today())}
function item(kind,x,description=''){const done=kind==='tasks'&&x.done;return `<article class="item ${done?'completed':''}">${kind==='tasks'?`<button class="check" aria-label="${done?'Réouvrir':'Terminer'} ${esc(x.title)}" data-act="toggle:tasks:${esc(x.id)}">${done?'✓':''}</button>`:''}<div class="details"><button class="item-title" data-act="edit:${kind}:${esc(x.id)}">${esc(x.title||x.name)}</button><div class="muted">${description}</div>${kind==='tasks'?(x.subtasks||[]).map((t,i)=>`<label class="subtask"><input type="checkbox" data-subtask="${esc(x.id)}" data-index="${i}" ${t.done?'checked':''}>${esc(t.text)}</label>`).join(''):''}${kind==='notes'?[...String(x.body||'').matchAll(/\[\[task:([a-zA-Z0-9_.@-]+)\]\]/g)].map(m=>get('tasks',m[1])?b('↗ '+esc(get('tasks',m[1]).title),'edit:tasks:'+m[1]):'<small>Tâche liée supprimée</small>').join(''):''}${x.attachment?b('↓ '+esc(x.attachment.name),`attachment:${kind}:${x.id}`):''}</div>${kind==='tasks'?`<button class="star ${['Haute','Urgente'].includes(x.priority)?'important':''}" aria-label="Priorité ${esc(x.priority||'Normale')} de ${esc(x.title)} : changer" data-act="star:${x.id}">★</button>`:''}<details class="item-menu"><summary aria-label="Actions pour ${esc(x.title)}">•••</summary><div class="actions">${b('Modifier',`edit:${kind}:${esc(x.id)}`)}${kind==='reminders'?b('Reporter 10 min',`snoozemin:${x.id}`)+b('Acquitter',`ack:${x.id}`):''}${kind==='admin'?b(x.archived?'Réactiver':'Archiver / renouveler',`archive:${x.id}`):''}${b('Supprimer',`delete:${kind}:${esc(x.id)}`,'danger')}</div></details></article>`}
function home(){const inRange=x=>{const d=due(x);return homeView==='today'?(!d||d<=today()):homeView==='week'?(!d||d<=LifeCore.shift(today(),6)):d>=today()};const ts=db.tasks.filter(x=>!x.done&&inRange(x)).sort(sortDue),es=db.events.flatMap(x=>LifeCore.occurrences(x,today(),LifeCore.shift(today(),homeView==='today'?0:homeView==='week'?6:60))).sort(sortDue);const rs=db.reminders.filter(x=>!x.done).sort(sortDue);const modules={tasks:['Aujourd’hui · Tâches',ts.map(x=>item('tasks',x,fmt(x.due)))],events:['Rendez-vous',es.map(x=>item('events',x,`${fmt(x.date)} · ${esc(x.time||'Journée entière')} · ${esc(x.calendar||'Personnel')}`))],reminders:['Rappels',rs.map(x=>item('reminders',x,`${fmt(x.date)} ${esc(x.time||'')}`))],routines:['Habitudes du jour',db.routines.filter(x=>!x.paused&&LifeCore.scheduled(x,today())).map(x=>habitCard(x,true))],admin:['Échéances à venir',db.admin.filter(x=>!x.archived).sort(sortDue).slice(0,5).map(x=>item('admin',x,fmt(x.date)))],focus:['Concentration',[`<p>${db.focus.filter(x=>x.date===today()).reduce((n,x)=>n+Number(x.minutes||0),0)} minutes aujourd’hui</p><button class="btn" data-nav="focus">Ouvrir le minuteur</button>`]]};const order=db.settings.home;return `<section class="hero"><div class="hero-landscape" aria-hidden="true"></div><div class="hero-copy"><small>VOTRE ESPACE, VOTRE RYTHME</small><h1>Bonjour${db.settings.name?' '+esc(db.settings.name):''}</h1><p>${new Date().toLocaleDateString('fr-FR',{weekday:'long',day:'numeric',month:'long'})}</p></div></section><div class="quote">« Planifier aujourd’hui, réussir demain. »</div><div class="metrics">${[['Tâches',db.tasks.filter(x=>!x.done).length,'tasks'],['RDV',es.length,'calendar'],['Habitudes',db.routines.filter(x=>!x.paused).length,'routines'],['Échéances',db.admin.filter(x=>!x.archived).length,'admin']].map(([l,n,p])=>`<button data-nav="${p}"><strong>${n}</strong><span>${l}</span></button>`).join('')}</div><div class="toolbar">${tabs([['today','Aujourd’hui'],['week','Semaine'],['upcoming','À venir']],homeView,'homeview')}${b(customizing?'Terminer':'Personnaliser','customize')}</div>${customizing?`<div class="notice">Déplace et redimensionne les modules. Les tâches et rappels restent disponibles.<div class="actions">${['events','routines','admin','focus'].map(k=>b((db.settings.home.includes(k)?'Masquer ':'Afficher ')+({events:'Rendez-vous',routines:'Habitudes',admin:'Administration',focus:'Concentration'})[k],'module:'+k)).join('')}${b('Disposition par défaut','layoutreset')}</div></div>`:''}<div class="dashboard">${order.map((k,i)=>{const m=modules[k];if(!m)return '';return `<section class="panel module ${db.settings.sizes?.[k]==='wide'?'wide':''} ${db.settings.heights?.[k]==='tall'?'module-tall':db.settings.heights?.[k]==='compact'?'module-compact':''}">${customizing?`<div class="custom-controls">${b('↑',`move:${i}:-1`)}${b('↓',`move:${i}:1`)}${b('Largeur',`size:${k}`)}${b('Hauteur',`height:${k}`)}</div>`:''}<h2>${m[0]}</h2>${m[1].join('')||empty('Rien à afficher pour cette période.')}</section>`}).join('')}</div><button class="fab" aria-label="Ajouter une tâche" data-act="add:tasks">+</button>`}
function taskDescription(x){return `${fmt(x.due)} · ${esc(x.priority||'Normale')}${x.category?' · '+esc(x.category):''}${x.project?' · '+esc(x.project):''}${x.repeat&&x.repeat!=='Aucune'?' · ↻ '+esc(x.repeat):''}${(x.depends||[]).some(id=>!get('tasks',id)?.done)?' · Prérequis incomplets':''}`}
function tasks(){let list=db.tasks.filter(x=>x.title.toLocaleLowerCase().includes(taskQuery.toLocaleLowerCase())&&(!taskCategory||x.category===taskCategory)&&(!taskProject||x.project===taskProject)).sort((a,b)=>Number(a.done)-Number(b.done)||sortDue(a,b));if(sub==='open')list=list.filter(x=>!x.done);if(sub==='done')list=list.filter(x=>x.done);if(sub==='tomorrow')list=list.filter(x=>x.due===tomorrow());if(sub==='future')list=list.filter(x=>x.due>=tomorrow());return title('Tâches',b('+ Ajouter','add:tasks'))+tabs([['','Toutes'],['open','Actives'],['tomorrow','Demain'],['future','À venir'],['done','Terminées']],sub,'filter')+`<details class="panel filters"><summary>Recherche et filtres avancés</summary><label>Recherche<input id="taskQuery" value="${esc(taskQuery)}"></label><label>Catégorie<select id="taskCategory"><option value="">Toutes</option>${[...new Set(db.tasks.map(x=>x.category).filter(Boolean))].map(v=>`<option ${taskCategory===v?'selected':''}>${esc(v)}</option>`).join('')}</select></label><label>Projet<select id="taskProject"><option value="">Tous</option>${[...new Set(db.tasks.map(x=>x.project).filter(Boolean))].map(v=>`<option ${taskProject===v?'selected':''}>${esc(v)}</option>`).join('')}</select></label>${b('Sauvegarder cette vue','saveview')}${(db.settings.taskViews||[]).map((v,i)=>b(esc(v.name),`loadview:${i}`)).join('')}</details><section class="panel"><h2>${sub==='tomorrow'?'Demain · '+fmt(tomorrow()):'Mes tâches'} <span class="pill">${list.length}</span></h2>${list.map(x=>item('tasks',x,taskDescription(x))).join('')||empty('Aucune tâche dans cette vue.')}</section>`}
function agenda(start,end){const entries=[...db.events.flatMap(x=>LifeCore.occurrences(x,start,end)).map(x=>({kind:'events',x})),...db.tasks.filter(x=>x.due>=start&&x.due<=end).map(x=>({kind:'tasks',x})),...db.reminders.filter(x=>!x.done&&x.date>=start&&x.date<=end).map(x=>({kind:'reminders',x}))].sort((a,b)=>sortDue(a.x,b.x)||(a.x.time||'').localeCompare(b.x.time||''));return entries.map(({kind,x})=>item(kind,x,`${fmt(due(x))} · ${esc(x.time||'Journée entière')}${x.timeZone?' · '+esc(x.timeZone):''}${x.repeat&&x.repeat!=='Aucune'?' · ↻':''}`)).join('')||empty('Aucun engagement sur cette période.')}
function calendar(){const y=calDate.getFullYear(),m=calDate.getMonth(),start=LifeCore.day(new Date(y,m,1)),end=LifeCore.day(new Date(y,m+1,0));let cells=['L','M','M','J','V','S','D'].map(v=>`<span class="weekday">${v}</span>`).join('');for(let i=0;i<(new Date(y,m,1).getDay()+6)%7;i++)cells+='<span></span>';const ev=db.events.flatMap(x=>LifeCore.occurrences(x,start,end));for(let d=1;d<=new Date(y,m+1,0).getDate();d++){const ds=LifeCore.day(new Date(y,m,d)),n=ev.filter(x=>x.date===ds).length+db.tasks.filter(x=>x.due===ds).length;cells+=`<button class="day ${ds===today()?'today':''} ${ds===selectedDate?'chosen':''}" data-act="day:${ds}" aria-label="${fmt(ds)}, ${n} engagement(s)"><b>${d}</b><span class="day-dots">${n?'●'.repeat(Math.min(3,n)):''}</span></button>`}const days=weekDays();return title('Calendrier',b('+ Événement','add:events'))+tabs([['day','Jour'],['week','Semaine'],['month','Mois'],['upcoming','À venir']],calView,'calview')+(calView==='month'?`<div class="calendar-layout"><section class="panel"><div class="monthbar">${b('‹','month:-1')}<h2>${calDate.toLocaleDateString('fr-FR',{month:'long',year:'numeric'})}</h2>${b('›','month:1')}</div><div class="calendar">${cells}</div></section><section class="panel"><h2>${fmt(selectedDate)}</h2>${agenda(selectedDate,selectedDate)}</section></div>`:calView==='week'?`<div class="weekgrid">${days.map(d=>`<section class="panel"><h2>${fmt(d)}</h2>${agenda(d,d)}</section>`).join('')}</div>`:`<section class="panel">${calView==='day'?`<label>Date<input type="date" id="agendaDate" value="${selectedDate}"></label>`:'<h2>Les 90 prochains jours</h2>'}${agenda(calView==='day'?selectedDate:today(),calView==='day'?selectedDate:LifeCore.shift(today(),90))}</section>`)+`<div class="actions">${b('Importer ICS','ics')}${b('Exporter ICS','exportics')}</div><p class="muted">Google Calendar : indisponible sans intégration autorisée. Calendriers nommés et fuseaux horaires par événement. Les répétitions sont calculées dans le calendrier local.</p>`}
function habitCard(x,compact=false){const days=weekDays(),h=x.history||[],done=days.filter(d=>h.includes(d)).length,target=Number(x.target||(x.frequency==='Hebdomadaire'?1:x.frequency==='Jours ouvrés'?5:7));return `<article class="habit"><div class="habit-top"><span class="habit-icon" aria-hidden="true">${x.paused?'Ⅱ':'❀'}</span><div><button class="item-title" data-act="edit:routines:${x.id}">${esc(x.title)}</button><small>${esc(x.goal||x.frequency||'Quotidienne')} · Série ${streak(x)}</small></div><strong>${done}/${target}</strong>${compact?'':`<details class="item-menu"><summary aria-label="Gérer ${esc(x.title)}">•••</summary><div class="actions">${b(x.paused?'Reprendre':'Pause',`pause:${x.id}`)}${b('Modifier',`edit:routines:${x.id}`)}${b('Supprimer',`delete:routines:${x.id}`,'danger')}</div></details>`}</div><div class="habit-days">${days.map(d=>`<button aria-label="${h.includes(d)?'Annuler':'Valider'} ${esc(x.title)} le ${fmt(d)}" title="${fmt(d)}" ${d>today()||!LifeCore.scheduled(x,d)||x.paused?'disabled':''} data-act="habitday:${x.id}:${d}" class="${h.includes(d)?'achieved':!LifeCore.scheduled(x,d)?'rest':''}">${h.includes(d)?'✓':new Date(d+'T12:00:00').toLocaleDateString('fr-FR',{weekday:'narrow'})}</button>`).join('')}</div></article>`}
function routines(){return title('Habitudes',b('+ Ajouter','add:routines'))+`<p class="muted">Semaine du ${fmt(weekDays()[0])} · Les jours de pause ne cassent pas la série.</p><div class="habit-grid">${db.routines.map(x=>habitCard(x)).join('')||empty('Crée ta première habitude.')}</div>`}
function notes(){if(sub==='lists')return baseNotes();const folders=[...new Set(db.notes.map(x=>x.category||'Divers'))];return title('Notes',b('+ Note','add:notes'))+tabs([['','Notes'],['lists','Listes']],sub,'filter')+`<div class="folder-grid">${folders.map((v,i)=>`<button class="folder" data-act="notefolder:${i}"><span>▱</span><b>${esc(v)}</b><small>${db.notes.filter(x=>(x.category||'Divers')===v).length} notes</small></button>`).join('')}</div><label>Rechercher une note<input id="noteQuery" value="${esc(noteQuery)}"></label><div class="actions">${b('Note depuis un modèle','template')}</div><section class="panel"><h2>Mes notes</h2>${db.notes.filter(x=>[x.title,x.body,x.category].join(' ').toLocaleLowerCase().includes(noteQuery.toLocaleLowerCase())).map(x=>item('notes',x,esc((x.body||'').slice(0,180)))).join('')||empty('Aucune note.')}</section>`}
function admin(){return title('Administration',b('+ Dossier','add:admin'))+tabs([['active','À traiter'],['future','À venir'],['repeat','Récurrent'],['archived','Archivés']],adminView,'adminview')+`<section class="panel">${db.admin.filter(x=>adminView==='archived'?x.archived:!x.archived&&(adminView==='future'?x.date>=today():adminView==='repeat'?x.repeat&&x.repeat!=='Aucune':true)).sort(sortDue).map(x=>item('admin',x,`Échéance : ${fmt(x.date)} · ${esc(x.category||'Général')}${x.repeat&&x.repeat!=='Aucune'?' · ↻ '+esc(x.repeat):''}`)).join('')||empty('Aucun dossier dans cette vue.')}</section>`}
function weekly(){return title('Planning hebdomadaire',b('Proposer une organisation','propose'))+`<p class="muted">Les propositions concernent uniquement les tâches sans date et sans prérequis incomplet. Elles restent à valider.</p>${proposal.length?`<section class="panel"><h2>Proposition à vérifier</h2>${proposal.map(p=>`<p>${esc(get('tasks',p.id)?.title)} → ${fmt(p.due)}</p>`).join('')}${b('Valider ces dates','applyproposal')}${b('Ignorer','discardproposal')}</section>`:''}<div class="weekgrid">${weekDays().map(d=>`<section class="panel"><h2>${fmt(d)}</h2>${agenda(d,d)}</section>`).join('')}</div>`}
function stats(){const days=Array.from({length:7},(_,i)=>LifeCore.shift(today(),i-6)),done=db.tasks.filter(x=>x.done).length,groups=Object.entries(db.focus.reduce((a,x)=>(a[x.title]=(a[x.title]||0)+Number(x.minutes||0),a),{})),totalMinutes=groups.reduce((n,x)=>n+x[1],0),colors=['#a871c2','#6f91c9','#d0a34d','#73977d','#b07a91'];let percent=0;const segments=groups.map(([k,n],i)=>{const from=percent;percent+=n/totalMinutes*100;return colors[i%colors.length]+' '+from+'% '+percent+'%'}).join(',');return title('Analyses')+baseStats().replace('<h1>Statistiques personnelles</h1>','')+`<div class="dashboard"><section class="panel"><h2>Habitudes · 7 derniers jours</h2><div class="chart" role="img" aria-label="Validations d’habitudes par jour">${days.map(d=>{const n=db.routines.filter(x=>(x.history||[]).includes(d)).length;return `<div><span style="height:${Math.max(3,n/Math.max(1,db.routines.length)*120)}px"></span><b>${n}</b><small>${d.slice(8)}</small></div>`}).join('')}</div></section><section class="panel"><h2>Répartition du temps enregistré</h2>${db.focus.length?`<div class="time-chart"><div class="donut" role="img" aria-label="${totalMinutes} minutes réparties par activité" style="background:conic-gradient(${segments})"><span>${totalMinutes} min</span></div><div class="legend">${groups.map(([k,n],i)=>`<p><i style="background:${colors[i%colors.length]}"></i>${esc(k)} <strong>${n} min</strong></p>`).join('')}</div></div>`:empty('Aucune session enregistrée. Aucune estimation de temps inventée.')}</section><section class="panel"><h2>Administration</h2><p>${db.admin.filter(x=>!x.archived&&x.date&&x.date<today()).length} échéance(s) dépassée(s)</p><p>${db.admin.filter(x=>x.archived).length} dossier(s) archivé(s)</p></section></div>`}
function data(){return title('Plus & paramètres')+`<div class="launcher">${sections.filter(([p])=>!['home','calendar','tasks','routines','data'].includes(p)).map(([p,l,i])=>`<button data-nav="${p}"><span>${i}</span>${l}</button>`).join('')}</div><section class="panel"><h2>Mon espace</h2><label>Prénom<input id="profileName" maxlength="60" value="${esc(db.settings.name||'')}"></label><label>Thème<select id="themeSelect"><option value="auto">Automatique</option><option value="light">Clair</option><option value="dark">Sombre</option></select></label></section><section class="panel"><h2>Sauvegardes et restauration</h2><p>Les documents sont inclus dans le JSON. Conserve une copie externe avant chaque mise à jour.</p><div class="actions">${b('Exporter JSON','backup')}${b('Restaurer JSON','restore')}${b('Exporter CSV','csv')}${b('Échange NEXUS','nexus')}${b('Demander stockage persistant','persiststorage')}</div><h3>Copies locales avant restauration</h3>${backupList().map((x,i)=>b(new Date(x.at).toLocaleString('fr-FR'),`localbackup:${i}`)).join('')||'<p class="muted">Aucune restauration effectuée.</p>'}</section><section class="panel"><h2>Capacités réelles</h2><p>Hors ligne après chargement complet. Rappels multiples affichés dans l’application à son ouverture et pendant son utilisation. Pas de notifications garanties lorsque la PWA est fermée. Google Calendar, cloud, chiffrement et widgets natifs : non activés. NEXUS : export uniquement, aucune synchronisation active.</p><p>Pièces jointes : 500 Ko par fichier. Le stockage du navigateur reste soumis à ses quotas.</p><p id="storageStatus" class="muted"></p><p id="offlineStatus" class="muted">Vérification du cache hors ligne…</p></section><section class="panel"><h2>Réinitialisation</h2><p>Une copie locale et un export externe sont recommandés.</p>${b('Réinitialiser cet espace','reset','danger')}</section>`}
function modalHTML(){let html=baseModalHTML();if(!modal)return html;const {kind,id}=modal,x=id?get(kind,id):{};let extra='';if(['tasks','events','notes','admin'].includes(kind)&&kind!=='admin')extra+=field('category','Catégorie / dossier','text',x.category||'');if(kind==='tasks')extra+=field('project','Projet / regroupement','text',x.project||'')+field('subtaskLines','Sous-tâches (une par ligne)','textarea',(x.subtasks||[]).map(t=>t.text).join('\n'));if(['tasks','events','admin'].includes(kind))extra+=field('alertLines','Rappels : minutes avant (séparées par virgules)','text',(x.alerts||[]).join(', '));if(['events','admin'].includes(kind))extra+=field('repeat','Récurrence','select',x.repeat||'Aucune','Aucune|Quotidienne|Hebdomadaire|Mensuelle|Annuelle');if(kind==='events')extra+=field('repeatUntil','Fin de récurrence (facultatif)','date',x.repeatUntil||'')+field('repeatCount','Nombre total d’occurrences (facultatif)','number',x.repeatCount||'')+field('timeZone','Fuseau IANA (vide = appareil)','text',x.timeZone||'')+field('duration','Durée en minutes','number',x.duration||60);if(kind==='routines')extra+=field('target','Objectif hebdomadaire (1–7)','number',x.target||7)+`<fieldset><legend>Jours (fréquence personnalisée ou hebdomadaire)</legend>${[1,2,3,4,5,6,0].map((d,i)=>`<label class="inline"><input type="checkbox" name="weekday" value="${d}" ${(x.weekdays||[1]).includes(d)?'checked':''}>${['Lun','Mar','Mer','Jeu','Ven','Sam','Dim'][i]}</label>`).join('')}</fieldset>`;if(kind==='notes')extra+=`<p class="muted">Liens internes : sélectionne une fiche à ouvrir.</p><div class="actions">${db.tasks.slice(0,12).map(t=>`<button type="button" class="btn alt" data-act="insertlink:${t.id}">${esc(t.title)}</button>`).join('')}</div>`;if(['tasks','events','notes','admin'].includes(kind))html=html.replace('class="modal"','class="modal long-form"');html=html.replace('<div class="actions"><button class="btn" type="submit">',extra+'<div class="actions"><button class="btn" type="submit">');html=html.replace('Aucune|Quotidienne|Hebdomadaire|Mensuelle','Aucune|Quotidienne|Hebdomadaire|Mensuelle');return html}
function backupList(){try{return JSON.parse(localStorage.getItem('life_os_backup_history_v2')||'[]')}catch{return []}}
async function restoreBackup(){const input=document.createElement('input');input.type='file';input.accept='.json';input.onchange=async()=>{try{if(!input.files.length)return;const incoming=LifeCore.validate(JSON.parse(await input.files[0].text()),defaults());if(!confirm('Remplacer les données de CETTE version de test par cette sauvegarde ? Une copie locale préalable sera conservée.'))return;commitRestore(incoming)}catch(e){alert(e.message)}};input.click()}
function commitRestore(incoming){const previous=structuredClone(db);try{localStorage.setItem('life_os_backup_history_v2',JSON.stringify([{at:new Date().toISOString(),data:previous},...backupList()].slice(0,3)));db=incoming;if(!persist())return;render();alert('Restauration terminée.')}catch(e){db=previous;alert('Copie préalable impossible : restauration annulée. Exporte tes données pour libérer du stockage.')}}
function action(s){const [cmd,k,id]=s.split(':');if(cmd==='dismissbanner'){bannerDismissed=true;const box=document.getElementById('reminderBanner');if(box)box.hidden=true;return}if(cmd==='derivedack'||cmd==='derivedsnooze'){const a=activeAlerts().find(a=>a.key===k);if(a){db.settings.alertStates=db.settings.alertStates||{};db.settings.alertStates[k]=cmd==='derivedack'?{ack:true}:{snoozeUntil:Date.now()+600000};persist();render();checkReminders()}return}if(cmd==='habitday'){const x=get('routines',k);if(!x||x.paused||id>today()||!LifeCore.scheduled(x,id))return;x.history=x.history||[];x.history=x.history.includes(id)?x.history.filter(d=>d!==id):[...x.history,id];persist();render();return}if(cmd==='module'){db.settings.home=db.settings.home.includes(k)?db.settings.home.filter(v=>v!==k):[...db.settings.home,k];persist();render();return}if(cmd==='homeview'){homeView=k;render();return}if(cmd==='calview'){calView=k;render();return}if(cmd==='day'){selectedDate=k;render();return}if(cmd==='customize'){customizing=!customizing;render();return}if(cmd==='layoutreset'){if(confirm('Restaurer la disposition par défaut sans supprimer de données ?')){db.settings.home=defaults().settings.home;db.settings.sizes={};db.settings.heights={};persist();render()}return}if(cmd==='move'){const i=Number(k),j=i+Number(id),a=db.settings.home;if(j>=0&&j<a.length)[a[i],a[j]]=[a[j],a[i]];persist();render();return}if(cmd==='height'){db.settings.heights=db.settings.heights||{};const h=db.settings.heights[k];db.settings.heights[k]=h==='compact'?'tall':h==='tall'?'normal':'compact';persist();render();return}if(cmd==='size'){db.settings.sizes=db.settings.sizes||{};db.settings.sizes[k]=db.settings.sizes[k]==='wide'?'normal':'wide';persist();render();return}if(cmd==='star'){const x=get('tasks',k);x.priority=x.priority==='Haute'?'Normale':'Haute';persist();render();return}if(cmd==='saveview'){const name=prompt('Nom de la vue');if(name){db.settings.taskViews=db.settings.taskViews||[];db.settings.taskViews.push({name,taskQuery,taskCategory,taskProject,sub});persist();render()}return}if(cmd==='loadview'){const v=db.settings.taskViews?.[Number(k)];if(v){taskQuery=String(v.taskQuery||'');taskCategory=String(v.taskCategory||'');taskProject=String(v.taskProject||'');sub=['','open','done','tomorrow','future'].includes(v.sub)?v.sub:'';render()}return}if(cmd==='notefolder'){noteQuery=[...new Set(db.notes.map(x=>x.category||'Divers'))][Number(k)]||'';render();return}if(cmd==='template'){open('notes');document.getElementById('f_title').value='Revue de semaine';document.getElementById('f_body').value='Réussites\n\nDifficultés\n\nPriorités de la semaine prochaine\n';return}if(cmd==='insertlink'){const el=document.getElementById('f_body');el.value+='\n[[task:'+k+']]';return}if(cmd==='adminview'){adminView=k;render();return}if(cmd==='archive'){const x=get('admin',k);if(!x.archived&&x.repeat&&x.repeat!=='Aucune'&&x.date){const next=dateAdd(x.date,x.repeat,x.repeatAnchor||x.date);if(!db.admin.some(t=>t.recurrenceParent===x.id&&t.date===next))db.admin.push({...x,id:uid(),date:next,repeatAnchor:x.repeatAnchor||x.date,recurrenceParent:x.id,archived:false})}x.archived=!x.archived;persist();render();return}if(cmd==='ack'){get('reminders',k).done=true;persist();render();return}if(cmd==='snoozemin'){const x=get('reminders',k),d=new Date(Date.now()+600000);x.date=LifeCore.day(d);x.time=d.toTimeString().slice(0,5);persist();render();return}if(cmd==='attachment'){const a=get(k,id)?.attachment;if(a){const link=document.createElement('a');link.href=a.data;link.download=a.name;link.click()}return}if(cmd==='propose'){proposal=db.tasks.filter(x=>!x.done&&!x.due&&!(x.depends||[]).some(id=>!get('tasks',id)?.done)).map((x,i)=>({id:x.id,due:LifeCore.shift(today(),Math.floor(i/3))}));render();if(!proposal.length)alert('Aucune tâche sans date et disponible à planifier.');return}if(cmd==='applyproposal'){if(confirm('Appliquer les dates proposées ?')){proposal.forEach(p=>{const x=get('tasks',p.id);if(x&&!x.done&&!x.due)x.due=p.due});persist();proposal=[];render()}return}if(cmd==='discardproposal'){proposal=[];render();return}if(cmd==='localbackup'){const x=backupList()[Number(k)];if(x&&confirm('Restaurer cette copie locale ? Les données actuelles seront remplacées.'))commitRestore(LifeCore.validate({app:'LIFE_OS',version:2,data:x.data},defaults()));return}if(cmd==='persiststorage'){navigator.storage?.persist?.().then(ok=>{document.getElementById('storageStatus').textContent=ok?'Stockage persistant accordé par le navigateur.':'Le navigateur n’a pas accordé le stockage persistant. Conserve des sauvegardes externes.'});return}if(cmd==='nexus'){download('LIFE_OS_NEXUS.json',JSON.stringify({format:'nexus-exchange',schemaVersion:1,sourceApp:'LIFE_OS',exported:new Date().toISOString(),data:db},null,2),'application/json');return}if(cmd==='toggle'){const x=get(k,id);if(!x.done&&(x.subtasks||[]).some(t=>!t.done)){alert('Termine les sous-tâches avant la tâche principale.');return}}baseAction(s)}
document.addEventListener('change',e=>{const el=e.target;if(el.dataset.subtask){const x=get('tasks',el.dataset.subtask);x.subtasks[Number(el.dataset.index)].done=el.checked;persist();return}if(el.id==='profileName'){db.settings.name=el.value.trim();persist()}if(el.id==='taskCategory'){taskCategory=el.value;render()}if(el.id==='taskProject'){taskProject=el.value;render()}if(el.id==='agendaDate'){selectedDate=el.value;render()}});
document.addEventListener('input',e=>{const key=e.target.id;if(key==='taskQuery'||key==='noteQuery'){if(key==='taskQuery')taskQuery=e.target.value;else noteQuery=e.target.value;const pos=e.target.selectionStart;render();const el=document.getElementById(key);el.focus();el.setSelectionRange(pos,pos);if(key==='taskQuery')el.closest('details').open=true}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&modal){modal=null;render()}if(e.key==='Tab'&&modal){const els=[...document.querySelectorAll('.modal button,.modal input,.modal textarea,.modal select,.modal a')].filter(x=>!x.disabled);const first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){last.focus();e.preventDefault()}else if(!e.shiftKey&&document.activeElement===last){first.focus();e.preventDefault()}}});
matchMedia('(prefers-color-scheme: light)').addEventListener('change',()=>{if(db.settings.theme==='auto')applyTheme()});
let bannerDismissed=false;
function activeAlerts(){const now=Date.now(),out=[],states=db.settings.alertStates||{};for(const kind of ['tasks','events','admin'])for(const x of db[kind]){if(x.done||x.archived)continue;const list=kind==='events'?LifeCore.occurrences(x,LifeCore.shift(today(),-1),LifeCore.shift(today(),366)):[x];for(const v of list){const ds=due(v);if(!ds)continue;const at=LifeCore.timestamp(ds,x.time,x.timeZone);if(kind==='events'&&at+Math.max(60,Number(x.duration||60))*60000+86400000<now)continue;for(const mins of x.alerts||[]){const key=encodeURIComponent([kind,x.id,ds,mins].join('|')),state=states[key]||{};if(at-mins*60000<=now&&!state.ack&&!(state.snoozeUntil>now))out.push({key,kind,x,date:ds,mins,at})}}}return out.sort((a,b)=>a.at-b.at)}
function reminders(){const derived=activeAlerts();return title('Rappels',b('+ Rappel','add:reminders'))+`<div class="notice">Rappels dans l’application uniquement. Les alertes quand la PWA est fermée ne sont pas garanties.</div><section class="panel"><h2>Alertes des tâches, événements et dossiers</h2>${derived.map(a=>`<article class="item"><div class="details"><b>${esc(a.x.title)}</b><div class="muted">${fmt(a.date)} · ${a.mins} min avant · ${esc(a.x.priority||'Normale')}</div><div class="actions">${b('Ouvrir',`edit:${a.kind}:${a.x.id}`)}${b('Reporter 10 min',`derivedsnooze:${a.key}`)}${b('Acquitter',`derivedack:${a.key}`)}</div></div></article>`).join('')||empty('Aucune alerte échue non acquittée.')}</section><section class="panel"><h2>Rappels personnels</h2>${db.reminders.slice().sort(sortDue).map(x=>item('reminders',x,`${fmt(x.date)} ${esc(x.time||'')} · ${esc(x.priority||'Normale')}${x.done?' · Acquitté':''}`)).join('')||empty('Aucun rappel personnel.')}</section>`}
function checkReminders(){if(modal||bannerDismissed)return;const now=Date.now(),manual=db.reminders.filter(x=>!x.done&&x.date&&LifeCore.timestamp(x.date,x.time)<=now);const found=[...manual,...activeAlerts().map(a=>a.x)];let box=document.getElementById('reminderBanner');if(!box){box=document.createElement('div');box.id='reminderBanner';box.className='reminder-banner';box.setAttribute?.('role','status');document.body.append(box)}box.hidden=!found.length;const content=found.length?`<button aria-label="Masquer les rappels" data-act="dismissbanner">×</button><b>${found.some(x=>x.priority==='Urgente')?'Alerte prioritaire':'Rappels dans l’application'}</b><p>${[...new Set(found.map(x=>x.title))].slice(0,4).map(esc).join(' · ')}</p><button class="btn alt" data-nav="reminders">Ouvrir les rappels</button>`:'';if(box.innerHTML!==content)box.innerHTML=content;box.classList?.toggle('critical',found.some(x=>x.priority==='Urgente'))}
async function offlineStatus(){const el=document.getElementById('offlineStatus');if(!el)return;if(!('serviceWorker' in navigator)){el.textContent='Service worker indisponible : utiliser HTTPS.';return}try{const names=await caches.keys();const cache=await caches.open(names.find(n=>n.startsWith('life-os-studio-'))||'life-os-empty');const urls=await cache.keys();el.textContent=urls.length>=14?'Cache hors ligne installé ('+urls.length+' ressources).':'Cache incomplet : attendre la fin du chargement avec une connexion.'}catch{el.textContent='Cache non accessible dans ce navigateur.'}}
setInterval(checkReminders,60000);window.addEventListener('online',render);window.addEventListener('offline',render);
if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').then(reg=>{reg.addEventListener('updatefound',()=>{const worker=reg.installing;worker?.addEventListener('statechange',()=>{if(worker.state==='installed'&&navigator.serviceWorker.controller){const box=document.createElement('div');box.className='notice';box.textContent='Mise à jour disponible : ferme puis rouvre LIFE OS après avoir enregistré tes modifications.';document.getElementById('app').prepend(box)}})})}).catch(()=>{});
window.addEventListener('storage',e=>{if(e.key===KEY){if(modal){alert('Les données ont changé dans un autre onglet. Ce formulaire est annulé pour préserver la version enregistrée.');modal=null}try{db=LifeCore.validate({app:'LIFE_OS',version:2,data:JSON.parse(e.newValue)},defaults());render()}catch{alert('Modification externe invalide : recharge avant de continuer.')}}if(e.key===TIMER_KEY){try{focusTimer=JSON.parse(e.newValue);if(page==='focus')render()}catch{}}});render();checkReminders();

})();
